select ideas.put_theses($j$[{"kind": "thesis", "scale": "micro", "stage": 0, "model": "claude-opus-5-5", "method": "session", "losers": [], "thesis_key": "ls_materials_aidc_uc_2027", "parent_key": "onsite_power_grid_bypass_2026", "origin": "decompose", "ecosystem": "power", "title": "연료전지 데이터센터의 부하 평활이 작은 커패시터 회사로 — LS머트리얼즈", "statement": "AI 데이터센터가 계통 대신 현장 연료전지로 전력을 만들면, 연료전지가 따라가지 못하는 부하 급변을 울트라커패시터(UC)가 받는다. LS머트리얼즈는 미국 수소연료전지사(유통사 iConnexion Asia 경유)에 초도 $4.7M(2026-11 출하)에 이어 ₩689억 본계약(2027-04-16~2028-03-17, 2025 연결매출의 44.85%, UC 연매출 ₩291억의 약 2.4배)을 받았고, 연내 추가 계약이면 누적 $100M 을 넘는다고 했다. 2027년 UC 매출이 두세 배가 되고 UC 부문이 흑자로 돌아서는지가 테제다.", "weakest_link": "₩689억 계약은 최종고객(미국 수소연료전지사)의 확정 발주이고, 2027-04-28까지 해지·20% 이상 감액·개시 연기 정정공시 없이 유지된다", "chain": [{"node": "component:fuel_cell", "claim": "AI 데이터센터 현장 발전 연료전지는 급격한 부하 변동을 혼자 따라가기 어렵다 — UC 가 흡수", "evidence": [{"url": "https://core.asiae.co.kr/article/2026101310052724755", "title": "아시아경제 — 美 수소연료전지사에 AIDC용 UC $51.5M, 초도 $4.7M", "date": "2026-10-13", "kind": "news"}]}, {"node": "component:supercapacitor", "claim": "같은 용도 수주가 업계 단위로 나온다 — 비나텍 ₩1,230억·₩1,195억 (2026-10)", "evidence": [{"url": "https://biz.sbs.co.kr/amp/article/20000341686", "title": "SBS Biz — 비나텍 데이터센터 슈퍼커패시터 아크벨 1,230억·산미나 1,195억", "date": "2026-10-23", "kind": "news"}]}, {"node": "company:ls_materials", "claim": "₩689억 본계약(연결매출 44.85%) + 초도 $4.7M, 연내 추가 시 누적 $100M+ 기대", "evidence": [{"url": "https://sateconomy.co.kr/news/view/1065575480990207", "title": "토요경제 — iConnexion Asia 경유, 연결매출 44.85%, 2027-04-16~2028-03-17, 선급금 없음, UC 1H26 매출 172억·OPM -1.5%", "date": "2026-10-27", "kind": "news"}, {"url": "https://ceoscoredaily.com/page/view/2026101416153725466", "title": "CEO스코어데일리 — 연내 추가 계약 시 1억달러 돌파 기대, UC 매출 2025 291억(19%)", "date": "2026-10-14", "kind": "news"}]}], "drivers": [{"id": "ls_aidc_uc_orders", "metric": "공시된 AIDC UC 누적 수주", "latest": "약 $56M (초도 $4.7M + 본계약 $51.5M, 2026-10)", "threshold": "≥ $100M (회사가 연내 기대)", "source": "https://ceoscoredaily.com